(async () => {
    let activeConversation = null;

    function endCurrentConversation() {
        if (activeConversation && activeConversation.log.length > 1) {
            console.log('Kora-ConversationManager: Conversation ended. Dispatching event.');
            document.dispatchEvent(new CustomEvent('KoraEvents.CONVERSATION_ENDED', { detail: activeConversation }));
        }
        activeConversation = null;
    }

    async function handleMessage(message_id) {
        const msg = (await getChatMessages(message_id))?.[0];
        if (!msg || msg.is_system || msg.is_hidden) return;

        const speakerName = msg.name;
        const isUser = msg.is_user;

        // 如果是玩家发言，或者发言者不是当前对话的参与者，则结束上一场对话
        if (isUser || (activeConversation && !activeConversation.participants.includes(speakerName))) {
            endCurrentConversation();
        }

        // 如果是NPC发言，则开始或继续一场对话
        if (!isUser) {
            if (!activeConversation) {
                activeConversation = { participants: [speakerName], log: [], startTime: Date.now() };
            }

            // 如果有新的NPC加入对话
            if (!activeConversation.participants.includes(speakerName)) {
                activeConversation.participants.push(speakerName);
            }

            activeConversation.log.push(`${speakerName}: ${msg.message}`);
            activeConversation.lastTimestamp = Date.now();
        }
    }

    // 定时检查超时的对话
    setInterval(() => {
        if (activeConversation && (Date.now() - activeConversation.lastTimestamp > 30000)) { // 30秒无新消息则超时
            console.log('Kora-ConversationManager: Conversation timed out.');
            endCurrentConversation();
        }
    }, 5000);

    if (window.Mvu && Mvu.events) {
        eventOn(tavern_events.MESSAGE_RECEIVED, handleMessage);
        eventOn(tavern_events.MESSAGE_SENT, handleMessage);
        console.log('Kora-ConversationManager v1.0: Script loaded.');
    }
})();

