(async () => {
    let activeStatusPanel = null;
    const panelClassName = 'kora-status-panel';
    const placeholderRegex = /<StatusPlaceHolderImpl\/>/g;

    function generateStatusBlock(variables) {
        const statData = variables.stat_data || {};
        const userData = statData.user?.[0] || {};
        const charData = statData.char || {};
        const worldData = statData.world?.[0] || {};
        const container = document.createElement('div');
        container.className = panelClassName;

        const style = document.createElement('style');
        style.textContent = `
            .kora-status-panel { background-color: #1a1a2e; border: 1px solid #4a4e69; border-radius: 8px; padding: 12px; color: #e0e0e0; font-family: sans-serif; margin-top: 10px; }
            .kora-action-bar { display: grid; grid-template-columns: repeat(auto-fit, minmax(100px, 1fr)); gap: 10px; margin-bottom: 10px; padding-bottom: 10px; border-bottom: 1px solid #4a4e69; }
            .kora-action-btn { background-color: #4e54c8; color: white; border: none; padding: 8px; border-radius: 4px; cursor: pointer; text-align: center; font-size: 0.9em; }
            .kora-action-btn:hover { background-color: #6a6edb; }
            .kora-tabs { display: flex; border-bottom: 1px solid #4a4e69; margin-bottom: 10px; }
            .kora-tab-btn { background: none; border: none; color: #8f94fb; padding: 10px 15px; cursor: pointer; font-size: 1em; }
            .kora-tab-btn.active { color: white; border-bottom: 2px solid white; }
            .kora-tab-content { display: none; padding-top: 10px; }
            .kora-tab-content.active { display: block; }
            .kora-header, .kora-user-stats { display: flex; justify-content: space-between; padding-bottom: 8px; margin-bottom: 8px; font-size: 0.9em; }
            .kora-user-stats { border-bottom: 1px solid #4a4e69; }
            .kora-building-list { list-style: none; padding: 0; }
            .kora-building-list li { background-color: #23253a; padding: 8px; border-radius: 4px; margin-bottom: 5px; display: flex; justify-content: space-between; align-items: center; }
            .kora-building-list .occupant { color: #8f94fb; font-weight: bold; }
            .kora-accordion-btn { background-color: #2c2f48; width: 100%; border: none; padding: 10px; text-align: left; color: #c0c0e0; cursor: pointer; border-radius: 4px; margin-top: 5px; }
            .kora-accordion-content { padding: 10px; background-color: #23253a; border-radius: 0 0 4px 4px; display: none; }
            .kora-favor-bar { background-color: #4a4e69; border-radius: 5px; overflow: hidden; height: 20px; width: 100%; margin: 5px 0; }
            .kora-favor-progress { background: linear-gradient(90deg, #4e54c8, #8f94fb); height: 100%; display: flex; align-items: center; justify-content: center; font-size: 0.8em; color: white; transition: width 0.5s ease; }
            .kora-thoughts, .kora-resident-thought { background-color: #1a1a2e; border-left: 3px solid #8f94fb; padding: 8px; margin-top: 8px; font-style: italic; font-size: 0.9em; }
            .kora-resident-thought { margin-bottom: 8px; }
            .kora-resident-thought strong { color: #e0e0e0; font-style: normal; }
            .kora-broadcast-list { list-style-type: decimal; padding-left: 20px; }
            .kora-broadcast-list li { margin-bottom: 5px; }
            .kora-placeholder-text { color: #777; font-style: italic; }
        `;
        container.appendChild(style);

        const actionBar = document.createElement('div');
        actionBar.className = 'kora-action-bar';
        const buttons = [{ label: '开始审核' }, { label: '驱逐审查目标' }, { label: '复核回归者' }, { label: '建造建筑' }];
        buttons.forEach(bInfo => {
            const btn = document.createElement('button');
            btn.className = 'kora-action-btn';
            btn.textContent = bInfo.label;
            btn.addEventListener('click', () => {
                const chatInput = parent.document.getElementById('send_textarea');
                if (chatInput) { chatInput.value = bInfo.label; chatInput.focus(); }
            });
            actionBar.appendChild(btn);
        });
        container.appendChild(actionBar);

        const tabs = document.createElement('div');
        tabs.className = 'kora-tabs';
        const tabConfigs = [
            { id: 'charStatus', text: '角色状态', default: true }, { id: 'residentInfo', text: '住户信息' },
            { id: 'apartmentLayout', text: '公寓建筑' }, { id: 'dailyBroadcast', text: '今日广播' },
        ];
        const tabElements = {};
        const contentElements = {};
        tabConfigs.forEach(config => {
            const btn = document.createElement('button');
            btn.className = `kora-tab-btn ${config.default ? 'active' : ''}`;
            btn.textContent = config.text;
            tabs.appendChild(btn);
            const content = document.createElement('div');
            content.className = `kora-tab-content ${config.default ? 'active' : ''}`;
            container.appendChild(content);
            tabElements[config.id] = content;
            btn.addEventListener('click', () => {
                Object.values(tabElements).forEach(c => c.classList.remove('active'));
                Object.values(tabs.children).forEach(t => t.classList.remove('active'));
                btn.classList.add('active');
                content.classList.add('active');
            });
        });
        container.insertBefore(tabs, container.children[1]);

        // Populate Tabs
        const header = document.createElement('div');
        header.className = 'kora-header';
        header.innerHTML = `<span>🗓️ 日期: ${worldData.date?.[0] || 'N/A'}</span><span>🕗 时间: ${worldData.time?.[0] || 'N/A'}</span>`;
        tabElements.charStatus.appendChild(header);

        const userStats = document.createElement('div');
        userStats.className = 'kora-user-stats';
        userStats.innerHTML = `<span>⭐ 等级: ${userData.level?.[0] || 1}</span><span>EXP: ${userData.exp?.[0] || 0} / ${ (userData.level?.[0] || 1) * 100 }</span>`;
        tabElements.charStatus.appendChild(userStats);

        for (const charId in charData) {
            const character = charData[charId]?.[0];
            if (character && character.status?.[0] === 'in_apartment') {
                const charName = _.get(character, 'name[0]', charId);
                const btn = document.createElement('button');
                btn.className = 'kora-accordion-btn';
                btn.textContent = `▼ ${charName}`;
                const contentDiv = document.createElement('div');
                contentDiv.className = 'kora-accordion-content';
                const favor = character.relationship?.[0] || 0;
                const favorBar = document.createElement('div'); favorBar.className = 'kora-favor-bar';
                const favorProgress = document.createElement('div');
                favorProgress.className = 'kora-favor-progress';
                favorProgress.style.width = `${favor}%`;
                favorProgress.textContent = `${favor}/100`;
                favorBar.appendChild(favorProgress);
                const thoughts = document.createElement('div');
                thoughts.className = 'kora-thoughts';
                thoughts.textContent = character.thoughts?.[0] || '...';
                contentDiv.appendChild(favorBar); contentDiv.appendChild(thoughts);
                btn.addEventListener('click', () => {
                    contentDiv.style.display = contentDiv.style.display === 'block' ? 'none' : 'block';
                    btn.textContent = contentDiv.style.display === 'block' ? `▲ ${charName}` : `▼ ${charName}`;
                });
                tabElements.charStatus.appendChild(btn);
                tabElements.charStatus.appendChild(contentDiv);

                const thoughtDiv = document.createElement('div');
                thoughtDiv.className = 'kora-resident-thought';
                thoughtDiv.innerHTML = `<strong>${charName}:</strong> <em>"${_.get(character, 'thoughts[0]', '...')}"</em>`;
                tabElements.residentInfo.appendChild(thoughtDiv);
            }
        }
        const roomOccupancy = {};
        for (const charId in charData) {
            const character = charData[charId]?.[0];
            if (character && character.status?.[0] === 'in_apartment') {
                const room = character.current_room?.[0];
                if (room && room !== '暂未入住' && room !== '隔离室') {
                    roomOccupancy[room] = _.get(character, 'name[0]', charId);
                }
            }
        }
        const buildingList = document.createElement('ul');
        buildingList.className = 'kora-building-list';
        const buildingLayout = {
            '1楼 - 公共与管理区': ['管理员房间', '隔离区', '厨房', '娱乐室', '储藏间'],
            '2楼 - 自建区': worldData.built_rooms?.[0] || [], '3楼 - 居住区': ['301-A', '302-B', '303-C', '304-D'],
            '4楼 - 居住区': ['401-A', '402-B', '403-C', '404-D'], '5楼 - 居住区': ['501-A', '502-B', '503-C', '504-D'],
        };
        for (const floor in buildingLayout) {
            const floorHeader = document.createElement('li');
            floorHeader.style.cssText = 'background-color: #2c2f48; font-weight: bold;';
            floorHeader.textContent = floor;
            buildingList.appendChild(floorHeader);
            buildingLayout[floor].forEach(room => {
                const roomLi = document.createElement('li');
                const occupant = roomOccupancy[room] || '空';
                roomLi.innerHTML = `<span>${room}</span><span class="occupant">${occupant}</span>`;
                buildingList.appendChild(roomLi);
            });
        }
        tabElements.apartmentLayout.appendChild(buildingList);
        const broadcastTraits = _.get(worldData, 'daily_broadcast_traits[0]', []);
        if (broadcastTraits.length > 0) {
            const list = document.createElement('ol');
            list.className = 'kora-broadcast-list';
            broadcastTraits.forEach(trait => {
                const item = document.createElement('li');
                item.textContent = trait;
                list.appendChild(item);
            });
            tabElements.dailyBroadcast.appendChild(list);
        } else {
            const placeholder = document.createElement('p');
            placeholder.className = 'kora-placeholder-text';
            placeholder.textContent = '请等待更新';
            tabElements.dailyBroadcast.appendChild(placeholder);
        }

        return container;
    }

    async function updateStatusPanel() {
        if (!activeStatusPanel || !parent.document.body.contains(activeStatusPanel)) {
            activeStatusPanel = null;
            return;
        }
        try {
            const variables = getVariables({ type: 'chat' });
            const newContentContainer = generateStatusBlock(variables);
            activeStatusPanel.innerHTML = newContentContainer.innerHTML;
        } catch (e) {
            console.error('Kora-UI: Phoenix update failed.', e);
        }
    }

    async function injectStatusPanel(message_id) {
         const $mes_text = retrieveDisplayedMessage(message_id);
         if (!$mes_text.length) return;
         const rawMessage = (await getChatMessages(message_id))?.[0]?.message;
         if (!rawMessage || !rawMessage.includes('<StatusPlaceHolderImpl/>')) return;
         if (activeStatusPanel && parent.document.body.contains(activeStatusPanel)) {
             $mes_text.html($mes_text.html().replace(placeholderRegex, ''));
             return;
         }
         const variables = await getVariables({ type: 'message', message_id: message_id });
         const statusContainer = generateStatusBlock(variables);
         const placeholderEl = $mes_text.find('pre:contains("<StatusPlaceHolderImpl/>")').first();
         if (placeholderEl.length > 0) {
             placeholderEl.replaceWith(statusContainer);
         } else {
             $mes_text.html($mes_text.html().replace(placeholderRegex, ''));
             $mes_text.append(statusContainer);
         }
         activeStatusPanel = statusContainer;
    }

    async function runInitialization() {
        parent.document.querySelectorAll(`.${panelClassName}`).forEach(panel => panel.remove());
        activeStatusPanel = null;

        if (!window.Mvu || !window.Mvu.events) {
            console.error('Kora-StatusPanel: MVU framework not detected.');
            return;
        }

        eventRemoveListener(Mvu.events.VARIABLE_UPDATE_ENDED, updateStatusPanel);
        eventRemoveListener(tavern_events.CHARACTER_MESSAGE_RENDERED, injectStatusPanel);

        eventOn(Mvu.events.VARIABLE_UPDATE_ENDED, updateStatusPanel);
        eventOn(tavern_events.CHARACTER_MESSAGE_RENDERED, injectStatusPanel);

        setTimeout(async () => {
            const chatMessages = document.querySelectorAll("#chat .mes[is_user='false'][is_system='false']");
            for(const node of chatMessages) {
                const mesid = node.getAttribute("mesid");
                if(mesid && !activeStatusPanel) {
                    await injectStatusPanel(Number(mesid));
                }
            }
        }, 200);

        console.log('Kora-StatusPanel v4.2 (Delayed Init Edition) initialized.');
    }

    eventOn(tavern_events.CHAT_CHANGED, runInitialization);
    eventOn(tavern_events.APP_READY, runInitialization);
})();

