// name: 时间流逝自动化脚本 v3.0 (叙事驱动版)
(async () => {
    /**
     * 时间计算辅助函数：为'YYYY-MM-DD HH:MM'格式的时间戳增加指定分钟数
     */
    function addMinutesToTimestamp(timestampStr, minsToAdd) {
        const date = new Date(timestampStr.replace(' ', 'T'));
        const originalDate = new Date(timestampStr.replace(' ', 'T'));
        date.setMinutes(date.getMinutes() + minsToAdd);
        const dayOverflow = Math.floor((date - originalDate) / (1000 * 60 * 60 * 24));
        const year = date.getFullYear();
        const month = String(date.getMonth() + 1).padStart(2, '0');
        const day = String(date.getDate()).padStart(2, '0');
        const hours = String(date.getHours()).padStart(2, '0');
        const minutes = String(date.getMinutes()).padStart(2, '0');
        const newTimestamp = `${year}-${month}-${day} ${hours}:${minutes}`;
        return { newTimestamp, dayOverflow };
    }

    /**
     * 核心时间流处理器，在AI每次生成消息后触发
     * 负责解析AI回复中的 <Kora_Time_Elapsed /> 指令
     */
    async function handleTimeElapsed(message_id) {
        try {
            const messageData = (await getChatMessages(message_id))?.[0];
            if (!messageData || messageData.role !== 'assistant' || messageData.is_system) return;

            const content = messageData.message;
            const timeElapsedRegex = /<Kora_Time_Elapsed\s+minutes="(\d+)"\s*\/?>/g;
            const match = timeElapsedRegex.exec(content);

            if (match && match[1]) {
                const minutesToAdd = parseInt(match[1], 10);
                if (isNaN(minutesToAdd)) return;

                // 从消息中移除指令标签
                const finalContent = content.replace(timeElapsedRegex, '').trim();
                await setChatMessages([{ message_id, message: finalContent }], { refresh: 'affected' });

                const variables = getVariables({ type: 'chat' });
                const currentDate = _.get(variables, 'stat_data.world.date[0]');
                const currentTime = _.get(variables, 'stat_data.world.time[0]');
                const initialTimestamp = `${currentDate} ${currentTime}`;

                // 如果时间跳跃过长，触发小故事生成
                if (minutesToAdd > 60) {
                    const residents = Object.values(_.get(variables, 'stat_data.char', {})).filter(c => _.get(c, '[0].status[0]') === 'in_apartment');
                    const residentList = residents.map(r => _.get(r, '[0].name[0]')).join(', ');
                    const promptEntry = (await SillyTavern.loadWorldInfo('[PROMPT] 时间跳跃小故事生成器'))?.entries?.[0];
                    if (promptEntry) {
                        let vignettePrompt = promptEntry.content
                            .replace('{{duration_hours}}', Math.round(minutesToAdd / 60))
                            .replace('{{resident_list}}', residentList || '无');
                        const vignette = await generate({ user_input: vignettePrompt });
                        await createChatMessages([{ role: 'assistant', is_system: true, message: `--- 在你休息的这段时间里，公寓里发生了一些事 ---` }, { role: 'assistant', message: vignette }]);
                    }
                }

                // 更新时间
                const timeUpdateResult = addMinutesToTimestamp(initialTimestamp, minutesToAdd);
                await updateVariablesWith(vars => {
                    const [newDate, newTime] = timeUpdateResult.newTimestamp.split(' ');
                    _.set(vars, 'stat_data.world.date[0]', newDate);
                    _.set(vars, 'stat_data.world.time[0]', newTime);
                    return vars;
                }, { type: 'chat' });

                // 派发事件
                if (timeUpdateResult.dayOverflow > 0) {
                    document.dispatchEvent(new CustomEvent('KoraEvents.DAY_CHANGED'));
                }
                document.dispatchEvent(new CustomEvent('KoraEvents.TIME_UPDATED'));
            }

        } catch (error) {
            console.error('Kora-TimeAutomation v3.0 Error:', error);
        }
    }

    eventOn(tavern_events.MESSAGE_RECEIVED, handleTimeElapsed);
    console.log('Kora-TimeAutomation v3.0 (Narrative-Driven): Script loaded.');
})();

(async () => {
          function enforceValueConstraints(variables) {
