           await setChatMessages([{ message_id: message_id_to_replace, message: '*你结束了当前事务，回到了公寓的日常工作中。*' }]);
        }
    }

    async function logSharedKnowledge(eventSummary, locationOrIds) {
        if (!eventSummary || !locationOrIds) return;
        const variables = getVariables({ type: 'chat' });
        const allChars = _.get(variables, 'stat_data.char', {});
        let finalIds = [];
        if (Array.isArray(locationOrIds)) {
            finalIds = locationOrIds;
        } else {
            for (const id in allChars) {
                if (_.get(allChars[id], '[0].current_room[0]') === locationOrIds) {
                    finalIds.push(id);
                }
            }
        }
        if (finalIds.length === 0) return;
        await updateVariablesWith(vars => {
            for (const id of finalIds) {
                const logPath = `stat_data.char.${id}.[0].knowledge_log[0]`;
                if (_.has(vars, logPath)) {
                    const currentLog = _.get(vars, logPath, []);
                    if (!currentLog.includes(eventSummary)) {
                        currentLog.push(eventSummary);
                        _.set(vars, logPath, currentLog);
                    }
                }
            }
            return vars;
        }, { type: 'chat' });
    }

    // #################################
    // ###  CHARACTER GENERATION AI  ###
    // #################################

    async function generateNewCharacter(overrides = {}) {
        try {
            const isPseudo = 'is_pseudo' in overrides ? overrides.is_pseudo : Math.random() < 0.50;
            let faction = "";
            if ('faction' in overrides) { faction = overrides.faction;
            } else {
                if (isPseudo) {
                    const factions = ['Peaceful', 'Beastly', 'Lost'];
                    faction = factions[Math.floor(Math.random() * factions.length)];
                } else {
                    const factions = ['Conservative', 'Maintenance', 'Explorer'];
                    faction = factions[Math.floor(Math.random() * factions.length)];
                }
            }
            let intelligence = 'intelligence' in overrides ? overrides.intelligence : Math.floor(Math.random() * 71) + 30;
            let special_ability = "无";
            if (isPseudo && Math.random() < 0.40) {
                const ability_generation_prompt = `You are a creative writer. Based on the concept of a "pseudo-human" who can subtly alter their body or reality, generate a short, one-sentence description of a unique, hidden special ability. Your response must be only the ability description itself.`;
                special_ability = await generate({ user_input: ability_generation_prompt });
                if (special_ability.startsWith('"') && special_ability.endsWith('"')) { special_ability = special_ability.substring(1, special_ability.length - 1); }
            }

            let communal_activities = [];
            if ('communal_activities' in overrides) {
                communal_activities = overrides.communal_activities;
            } else {
                const activity_prompt = `You are a game designer. Based on the following character profile (Faction: ${faction}), generate a list of 1 to 3 specific 'communal activities' they enjoy or are good at. These activities must be things that can be done in a common area like a kitchen, living room, or workshop. Examples: '擅长烘焙蛋糕', '喜欢组织牌局', '是个修理电器的专家', '会弹吉他', '热衷于打扫公共卫生'. Respond with a simple comma-separated list.`;
                const activities_str = await generate({ user_input: activity_prompt });
                if (activities_str) {
                    communal_activities = activities_str.split(',').map(s => s.trim());
                }
            }

            const jsonFormat = `\n\`\`\`json\n{\n  "name": "A random Chinese female name",\n  "traits": "A short personality trait",\n  "appearance": "A short appearance description",\n  "clothing": "A short clothing description",\n  "thoughts": "A short, first-person inner thought",\n  "personal_belongings": ["An item reflecting their personality", "Another personal item"]\n}\n\`\`\`\n`;
            let generationPrompt = `You are a creative writing assistant. Your task is to generate an identity for a female character. Faction: ${faction}. Your entire response MUST be only the following JSON structure:${jsonFormat}`;
            let generatedData = { name: overrides.name, traits: overrides.traits, appearance: overrides.appearance, clothing: overrides.clothing, thoughts: overrides.thoughts, personal_belongings: overrides.personal_belongings };
            if (!generatedData.name || !generatedData.appearance) {
                 const responseJson = await generate({ user_input: generationPrompt, temperature: 1.1 });
                 const jsonMatch = responseJson.match(/\{[\s\S]*\}/);
                 if (!jsonMatch) throw new Error("No JSON object found.");
                 const parsedData = JSON.parse(jsonMatch[0]);
                 generatedData = { ...generatedData, ...parsedData };
            }
            const finalCharObject = {
                "name": [generatedData.name, ""], "traits": [generatedData.traits || "未知", ""], "appearance": [generatedData.appearance, ""], "clothing": [generatedData.clothing || "未知", ""], "thoughts": [generatedData.thoughts || "...", ""], "is_pseudo": [isPseudo, ""], "relationship": [overrides.relationship || Math.floor(Math.random() * 51) + 20, ""], "favor": [overrides.relationship || 50, ""], "status": [overrides.status || "locked", ""], "current_room": [overrides.current_room || "隔离室", ""], "intelligence": [intelligence, ""], "special_ability": [overrides.special_ability || special_ability, ""], "knowledge_log": [["$__META_EXTENSIBLE__$"], ""], "faction": [faction, ""], "matched_traits_log": [{}, ""], "personal_belongings": [generatedData.personal_belongings || [], ""], "communal_activities": [communal_activities, ""]
            };
            return finalCharObject;
        } catch (e) {
            console.error("Kora-Generator: Error.", e);
            return { /* Fallback */ };
        }
    }

    // #################################
    // ### EVENT & COMMAND HANDLERS  ###
    // #################################

    async function handleKnowledgeLogging(message_id) {
        const messageData = (await getChatMessages(message_id))[0];
        if (!messageData || messageData.is_hidden) return;
        const content = messageData.message;
        let contentModified = false;
        let finalContent = content;
        const privateLogRegex = /<Kora_Log_Private\s+event="([^"]+)"\s+participants="([^"]+)"\s*\/?>/g;
        let privateMatch;
        while ((privateMatch = privateLogRegex.exec(content)) !== null) {
            contentModified = true;
            finalContent = finalContent.replace(privateMatch[0], '');
            const eventToLog = privateMatch[1];
            const participantNames = privateMatch[2].split(',').map(name => name.trim());
            const variables = getVariables({ type: 'chat' });
            const allChars = _.get(variables, 'stat_data.char', {});
            const participantIds = participantNames.map(name => {
                if (name.toLowerCase() === 'user') return null;
                return Object.keys(allChars).find(id => _.get(allChars[id], '[0].name[0]') === name);
            }).filter(id => id);
            if (participantIds.length > 0) {
                 await updateVariablesWith(vars => {
                    for (const id of participantIds) {
                        const logPath = `stat_data.char.${id}.[0].knowledge_log[0]`;
                        if (_.has(vars, logPath)) {
                            const currentLog = _.get(vars, logPath, []);
                            if (!currentLog.includes(eventToLog)) { currentLog.push(eventToLog); _.set(vars, logPath, currentLog); }
                        }
                    }
                    return vars;
                }, { type: 'chat' });
            }
        }
        if (contentModified) {
            await setChatMessages([{ message_id, message: finalContent.trim() }], { refresh: 'affected' });
        }
    }

    async function handleNpcRegistration(message_id) {
        const messageData = (await getChatMessages(message_id))[0];
        if (!messageData || messageData.role !== 'assistant' || messageData.is_hidden || messageData.is_system) return;
        const content = messageData.message;
        const registrationRegex = /<Kora_Register_NPC\s+([^>]+)\/>/g;
        let match;
        let contentModified = false;
        let finalContent = content;
        while ((match = registrationRegex.exec(content)) !== null) {
            contentModified = true;
            finalContent = finalContent.replace(match[0], '');
            const attrs = match[1];
            const overrideRegex = /(\w+)=["']([^"']+)["']|(\w+)=([^\s>]+)/g;
            let attrMatch;
            const overrides = {};
            while ((attrMatch = overrideRegex.exec(attrs)) !== null) {
                const key = attrMatch[1] || attrMatch[3];
                let value = attrMatch[2] || attrMatch[4];
                if (value.toLowerCase() === 'true') value = true;
                else if (value.toLowerCase() === 'false') value = false;
                else if (!isNaN(Number(value))) value = Number(value);
                overrides[key] = value;
            }
            if (overrides.name) {
                const newCharObject = await generateNewCharacter(overrides);
                const charId = 'char_' + Date.now();
                await updateVariablesWith(vars => { _.set(vars, `stat_data.char.${charId}`, [newCharObject, ""]); return vars; }, { type: 'chat' });
            }
        }
        if (contentModified) {
            await setChatMessages([{ message_id, message: finalContent.trim() }], { refresh: 'affected' });
        }
    }

    async function handleNpcMovement(message_id) {
        const messageData = (await getChatMessages(message_id))[0];
        if (!messageData || messageData.role !== 'assistant' || messageData.is_hidden) return;
        const content = messageData.message;
        const moveRegex = /<Kora_Move_To\s+room="([^"]+)"\s*\/?>/g;
        let match;
        let contentModified = false;
        let finalContent = content;
        while ((match = moveRegex.exec(content)) !== null) {
            contentModified = true;
            finalContent = finalContent.replace(match[0], '');
            const targetRoom = match[1];
            var last_message = getvar('main.raw_prompt').split('### Instruction:')[0].trim().split('\n').pop();
            var speaker_match = last_message.match(/^([^：:]+)[：:]/);
            if (!speaker_match) continue;
            const speaker_name = speaker_match[1].trim();
            const variables = getVariables({ type: 'chat' });
            const allChars = _.get(variables, 'stat_data.char', {});
            const speakerId = Object.keys(allChars).find(id => _.get(allChars[id], '[0].name[0]') === speaker_name);
            if (speakerId) {
                await updateVariablesWith(vars => {
                    const roomPath = `stat_data.char.${speakerId}.[0].current_room[0]`;
                    _.set(vars, roomPath, targetRoom);
                    return vars;
                }, { type: 'chat' });
            }
        }
        if (contentModified) {
            await setChatMessages([{ message_id, message: finalContent.trim() }], { refresh: 'affected' });
        }
    }

    async function handlePlayerCommands(message_id) {
        const messageData = (await getChatMessages(message_id))[0];
        if (!messageData || messageData.role !== 'user' || messageData.is_hidden) return;
        const content = messageData.message;
        const commandText = content.trim().split('\n').pop();
        const variables = getVariables({ type: 'chat' });
        const targetId = _.get(variables, 'stat_data.world.vetting_target[0]');

        const logTraitsRegex = /<Kora_Log_Traits\s+traits="([^"]+)"\s*\/?>/g;
        const logMatch = logTraitsRegex.exec(content);
        if (logMatch && logMatch[1] && targetId) {
            const traitsToLog = logMatch[1].split('|').map(t => t.trim()).filter(t => t);
            const currentDate = _.get(variables, 'stat_data.world.date[0]');
            if (traitsToLog.length > 0 && currentDate) {
                await updateVariablesWith(vars => {
                    const logPath = `stat_data.char.${targetId}.[0].matched_traits_log[0]`;
                    const dailyLogPath = `${logPath}.${currentDate}`;
                    const existingLog = _.get(vars, dailyLogPath, []);
                    _.set(vars, dailyLogPath, _.union(existingLog, traitsToLog));
                    return vars;
                }, { type: 'chat' });
            }
            const finalContent = content.replace(logTraitsRegex, '').trim();
            return setChatMessages([{ message_id, message: finalContent }]);
        }

        if (commandText.startsWith('/goto')) {
            const roomName = commandText.replace('/goto', '').trim();
            if (roomName) {
                await updateVariablesWith(vars => {
                    _.set(vars, 'stat_data.user.current_room[0]', roomName);
                    return vars;
                }, {type: 'chat'});
                return setChatMessages([{ message_id, is_hidden: true }]);
            }
        }

        if (commandText === '开始审核') {
            if (_.get(variables, 'stat_data.world.vetting_status[0]') !== 'daily_life') { return setChatMessages([{ message_id, is_hidden: true }]); }
            const newCharObject = await generateNewCharacter();
            const charId = 'char_' + Date.now();
            await updateVariablesWith(vars => {
                _.set(vars, `stat_data.char.${charId}`, [newCharObject, ""]);
                _.set(vars, 'stat_data.world.vetting_status[0]', 'active');
                _.set(vars, 'stat_data.world.vetting_target[0]', charId);
                return vars;
            }, { type: 'chat' });
            await logSharedKnowledge(`一位名叫 ${newCharObject.name[0]} 的新来客抵达了`, '隔离室');
            return setChatMessages([{ message_id, message: `*你准备开始对新来客【${newCharObject.name[0]}】进行审查。*` }]);
        }

        if (commandText === '批准入住') {
            if (targetId) {
                const targetName = _.get(variables, `stat_data.char.${targetId}.[0].name[0]`);
                await updateVariablesWith(vars => { _.set(vars, `stat_data.char.${targetId}.[0].status[0]`, 'in_apartment'); return vars; }, { type: 'chat' });
                await logSharedKnowledge(`${targetName} 通过审查并入住`, '隔离室');
                await endVettingProcess(message_id);
            }
            return;
        }

        if (commandText === '驱逐审查目标' || commandText === '放弃审查' || commandText === '处决目标') {
            if (targetId) {
                const targetName = _.get(variables, `stat_data.char.${targetId}.[0].name[0]`);
                let eventText = "";
                if (commandText === '处决目标') { eventText = `${targetName} 在审查中被处决`; }
                else if (commandText === '驱逐审查目标') { eventText = `${targetName} 在审查后被驱逐`; }
                else { eventText = `${targetName} 在审查中自行离开`; }
                await updateVariablesWith(vars => { delete vars.stat_data.char[targetId]; return vars; }, { type: 'chat' });
                await logSharedKnowledge(eventText, '隔离室');
                await endVettingProcess(message_id);
            }
            return;
        }
    }

    function logXpEvents(oldVars, newVars) {
        try {
            if (!oldVars || !newVars) return;
            const oldChars = _.get(oldVars, 'stat_data.char', {});
            const newChars = _.get(newVars, 'stat_data.char', {});
            let eventsToLog = [];
            for (const charId in newChars) {
                if (!_.has(oldChars, charId)) continue;
                const oldRoom = _.get(oldChars, `${charId}.[0].current_room[0]`);
                const newRoom = _.get(newChars, `${charId}.[0].current_room[0]`);
                if (oldRoom === '隔离室' && newRoom !== '隔离室' && newRoom !== '暂未入住') {
                    const isPseudo = _.get(newChars, `${charId}.[0].is_pseudo[0]`);
                    const charName = _.get(newChars, `${charId}.[0].name[0]`, charId);
                    eventsToLog.push(isPseudo ? { type: 'let_in_pseudo', value: -10, char: charName } : { type: 'let_in_normal', value: 20, char: charName });
                }
            }
            if (eventsToLog.length > 0) {
                updateVariablesWith(vars => {
                    const currentLog = _.get(vars, 'stat_data.world.daily_xp_log[0]', []);
                    _.set(vars, 'stat_data.world.daily_xp_log[0]', [...currentLog, ...eventsToLog]);
                    return vars;
                });
            }
        } catch (e) {
            console.error('Kora-XP-Manager (logXpEvents) Error:', e);
        }
    }

    async function settleDailyXp() {
        let summaryMessage = '';
        await updateVariablesWith(vars => {
            const log = _.get(vars, 'stat_data.world.daily_xp_log[0]', []);
            if (log.length === 0) { summaryMessage = '[每日总结]: 今日无经验变化。'; return vars; }
            const totalXpChange = log.reduce((sum, event) => sum + event.value, 0);
            const oldExp = _.get(vars, 'stat_data.user.exp[0]', 0);
            const oldLevel = _.get(vars, 'stat_data.user.level[0]', 1);
            const newExp = oldExp + totalXpChange;
            const newLevel = Math.floor(newExp / 100) + 1;
            let buildChargesGained = 0; let levelUpMessage = '';
            if (newLevel > oldLevel) {
                buildChargesGained = newLevel - oldLevel;
                levelUpMessage = `\n恭喜升级！你升到了 ${newLevel} 级，获得了 ${buildChargesGained} 次建造次数！`;
            }
            _.set(vars, 'stat_data.user.exp[0]', newExp);
            _.set(vars, 'stat_data.user.level[0]', newLevel);
            if (buildChargesGained > 0) { _.set(vars, 'stat_data.user.build_charges[0]', _.get(vars, 'stat_data.user.build_charges[0]', 0) + buildChargesGained); }
            _.set(vars, 'stat_data.world.daily_xp_log[0]', []);
            summaryMessage = `[每日总结]: 您今日的经验变化为 ${totalXpChange >= 0 ? '+' : ''}${totalXpChange}。当前总经验: ${newExp}。${levelUpMessage}`;
            return vars;
        }, { type: 'chat' });
        if (summaryMessage && !summaryMessage.includes('无经验变化')) {
            await createChatMessages([{ role: 'system', message: summaryMessage }]);
        }
    }

    async function handleCharacterReturn(event) {
        const { charId: originalCharId, isRealCharacter: isOriginalReturning, originalCharName: nameOfOriginal, outingReason } = event.detail;
        const variables = getVariables({ type: 'chat' });
        if (isOriginalReturning) {
             await createChatMessages([{ role: 'system', message: `[SYSTEM]: 真正的 ${nameOfOriginal} 历经艰险，终于回到了公寓门口！` }]);
             await updateVariablesWith(vars => { _.set(vars, `stat_data.char.${originalCharId}.[0].status[0]`, 'in_apartment'); _.set(vars, `stat_data.char.${originalCharId}.[0].current_room[0]`, '隔离室'); return vars; }, {type: 'chat'});
             return;
        }
        const originalCharData = _.get(variables, `stat_data.char.${originalCharId}`);
        if (!originalCharData) return;
        const originalChar = originalCharData[0];
        const originalName = originalChar.name[0];
        if (Math.random() < 0.50) {
            const doppelgangerObject = await generateNewCharacter({ name: originalName, appearance: originalChar.appearance[0], clothing: originalChar.clothing[0], is_pseudo: true, status: 'locked', current_room: '隔离室'});
            const doppelgangerId = 'char_' + Date.now();
            const delayHours = Math.floor(Math.random() * 4) + 2;
            const currentTime = `${_.get(variables, 'stat_data.world.date[0]')} ${_.get(variables, 'stat_data.world.time[0]')}`;
            const realReturnTimestamp = addHoursToTimestamp(currentTime, delayHours);
            document.dispatchEvent(new CustomEvent('KoraEvents.CHARACTER_DEPARTED', { detail: { charId: originalCharId, returnTimestamp: realReturnTimestamp, isRealCharacter: true, originalCharName: originalName } }));
            await updateVariablesWith(vars => {
                _.set(vars, `stat_data.char.${doppelgangerId}`, [doppelgangerObject, ""]);
                _.set(vars, `stat_data.world.vetting_status[0]`, 'review_outing');
                _.set(vars, `stat_data.world.vetting_target[0]`, doppelgangerId);
                return vars;
            }, { type: 'chat' });
        } else {
            if (Math.random() < 0.30) {
                const itemPrompt = `A character named ${originalName} (Faction: ${originalChar.faction[0]}, Traits: ${originalChar.traits[0]}) just returned from an outing where they were "${outingReason}". They found a small, interesting item as a souvenir. What item did they bring back? Respond with only the item's name.`;
                const newItem = await generate({ user_input: itemPrompt });
                if (newItem) {
                    await updateVariablesWith(vars => {
                        const belongingsPath = `stat_data.char.${originalCharId}.[0].personal_belongings[0]`;
                        const belongings = _.get(vars, belongingsPath, []);
                        belongings.push(newItem);
                        _.set(vars, belongingsPath, belongings);
                        return vars;
                    }, { type: 'chat' });
                    await createChatMessages([{ role: 'system', message: `[SYSTEM]: ${originalName} 在整理口袋时，发现了一件她从外面带回来的小东西：${newItem}。` }]);
                }
            }
            await updateVariablesWith(vars => {
                _.set(vars, `stat_data.char.${originalCharId}.[0].status[0]`, 'in_apartment');
                _.set(vars, `stat_data.char.${originalCharId}.[0].current_room[0]`, '隔离室');
                _.set(vars, `stat_data.world.vetting_status[0]`, 'review_outing');
                _.set(vars, `stat_data.world.vetting_target[0]`, originalCharId);
                return vars;
            }, { type: 'chat' });
        }
        await createChatMessages([{ role: 'system', message: `[SYSTEM]: “${originalName}”已返回，正在隔离室等待您的安全复核。` }]);
    }

    // #################################
    // ###   SCRIPT INITIALIZATION   ###
    // #################################
    if (window.Mvu && Mvu.events) {
        eventOn(Mvu.events.VARIABLE_UPDATE_ENDED, (oldVars, newVars) => { if (oldVars && newVars) logXpEvents(oldVars, newVars); });
        document.addEventListener('KoraEvents.DAY_CHANGED', settleDailyXp);
        eventOn(tavern_events.MESSAGE_SENT, handlePlayerCommands);
        eventOn(tavern_events.MESSAGE_RECEIVED, handleNpcRegistration);
        eventOn(tavern_events.MESSAGE_SENT, handleKnowledgeLogging);
        eventOn(tavern_events.MESSAGE_RECEIVED, handleKnowledgeLogging);
        eventOn(tavern_events.MESSAGE_RECEIVED, handleNpcMovement);
        document.addEventListener('KoraEvents.CHARACTER_RETURN_PENDING', handleCharacterReturn);
        console.log('Kora-ExperienceManager v17.0 (Communal Living Edition): Script loaded.');
    } else {
        console.error('Kora-ExperienceManager: MVU framework not detected.');
    }
})();

// [Tavern Helper Script]
// name: 广播管理器脚本 v2.1 (格式优化版)
(async () => {
    let lastBroadcastDate = null;
    let broadcastIsPending = false;

    /**
     * 核心广播执行函数
     */
    async function executeBroadcast() {
        const variables = getVariables({ type: 'chat' });
        const currentDate = _.get(variables, 'stat_data.world.date[0]');

        lastBroadcastDate = currentDate;
        broadcastIsPending = false;

        const wi_entry = (await SillyTavern.loadWorldInfo('PROMPT_GENERATE_BROADCAST_TRAITS'))?.entries?.[0];
        if (!wi_entry) return;

        const generated_yaml = await generate({ user_input: wi_entry.content });
        const traits_match = generated_yaml.match(/traits:\s*\n(\s*-\s*<q>".*?"<\/q>\s*\n?)+/);

        if (traits_match && traits_match[0]) {
            const traits = traits_match[0].split('\n').map(t => t.trim().replace(/-\s*<q>"|<\/q>"/g, '')).filter(t => t);
            if (traits.length === 3) {
                await updateVariablesWith(vars => {
                    _.set(vars, 'stat_data.world.daily_broadcast_traits[0]', traits);
                    return vars;
                }, { type: 'chat' });

                // Kora注：已按您的要求修改广播格式
                const broadcastMessage = `[每日广播 - ${currentDate}]:\n伪人研究局提醒所有幸存者，今日请注意以下特征：\n1. ${traits[0]}\n2. ${traits[1]}\n3. ${traits[2]}\n\n（注意：以上特征仅在今日08:00至明日08:00间，对新来客的初次审查有效。）`;
                await createChatMessages([{ role: 'system', message: broadcastMessage }]);
            }
        }
    }

    /**
     * 检查并决定是否触发或延迟广播
     */
    async function checkAndScheduleBroadcast() {
        try {
            const variables = getVariables({ type: 'chat' });
            const currentDate = _.get(variables, 'stat_data.world.date[0]');
            const currentTime = _.get(variables, 'stat_data.world.time[0]');
            const vettingStatus = _.get(variables, 'stat_data.world.vetting_status[0]');
            if (!currentDate || !currentTime) return;

            if (currentTime >= '08:00' && currentDate !== lastBroadcastDate) {
                if (vettingStatus !== 'daily_life') {
                    broadcastIsPending = true;
                    return;
                }
                await executeBroadcast();
            }
        } catch (e) { console.error("Kora-BroadcastManager (Scheduler) Error:", e); }
    }

    /**
     * 监听stat_data的更新，以触发待处理的广播
     */
    async function checkPendingBroadcast(oldVars, newVars) {
        if (!broadcastIsPending) return;
        const oldStatus = _.get(oldVars, 'stat_data.world.vetting_status[0]');
        const newStatus = _.get(newVars, 'stat_data.world.vetting_status[0]');
        if (oldStatus !== 'daily_life' && newStatus === 'daily_life') {
            await executeBroadcast();
        }
    }

    /**
     * 在新的一天重置状态
     */
    async function clearOldBroadcast() {
        lastBroadcastDate = null;
        broadcastIsPending = false;
        await updateVariablesWith(vars => {
            _.set(vars, 'stat_data.world.daily_broadcast_traits[0]', []);
            return vars;
        }, { type: 'chat' });
    }

    // 脚本初始化
    if (window.Mvu && Mvu.events) {
        document.addEventListener('KoraEvents.DAY_CHANGED', clearOldBroadcast);
        document.addEventListener('KoraEvents.TIME_UPDATED', checkAndScheduleBroadcast);
        eventOn(Mvu.events.VARIABLE_UPDATE_ENDED, checkPendingBroadcast);
        console.log('Kora-BroadcastManager v2.1 (Format Optimized): Script loaded.');
    } else {
        console.error('Kora-BroadcastManager: MVU framework not detected.');
    }
})();

// Kora注：这是一个酒馆助手(Tavern Helper)脚本。
// 它的唯一职责是，在后台捕获“待初始化”的角色，并驱动AI为其生成唯一的姓名和性格。
(async () => {
    // Kora注：这是脚本的核心函数，在每次后台变量更新后都会被触发。
    async function supervisedGeneration(variables) {
        try {
            const charData = _.get(variables, 'stat_data.char', {});
            let updateNeeded = false; // 是否需要更新变量的旗标

            // 遍历所有角色，寻找需要初始化的“半成品”
            for (const charId in charData) {
                const character = charData[charId][0];
                if (character && character.status && character.status[0] === 'initializing') {

                    // --- 步骤1: 构建生成式提示词 ---
                    const generationPrompt = `
You are a creative writing assistant. Your task is to generate a unique identity for a female character in a tense, survival-horror setting.

**CONSTRAINTS:**
1.  The name must be a common Chinese name.
2.  Generate exactly ONE personality trait. It should be a short, descriptive phrase.
3.  Your entire response MUST be only the following JSON structure, with no other text.

**OUTPUT FORMAT:**
\`\`\`json
{
  "name": "A random Chinese female name",
  "traits": "A short personality trait"
}
\`\`\`
`;
                    // --- 步骤2: 在后台调用AI进行创作 ---
                    // 'generate'函数会悄无声息地在后台完成，不会显示在聊天记录里。
                    const responseJson = await generate({ user_input: generationPrompt });

                    // --- 步骤3: 解析AI返回的数据 ---
                    let generatedData;
                    try {
                        // 尝试从AI返回的文本中提取出JSON部分
                        const jsonMatch = responseJson.match(/\{[\s\S]*\}/);
                        if (!jsonMatch) throw new Error("No JSON object found in AI response.");
                        generatedData = JSON.parse(jsonMatch[0]);

                        if (!generatedData.name || !generatedData.traits) {
                            throw new Error("Generated JSON is missing 'name' or 'traits' field.");
                        }
                    } catch (e) {
                        console.error("Kora-Generator: Failed to parse AI response. Using fallback.", e);
                        // 如果解析失败，使用备用数据以保证系统不崩溃
                        generatedData = { name: "神秘的幸存者", traits: "沉默寡言" };
                    }

                    // --- 步骤4: 更新角色数据 ---
                    // 将AI生成的数据写回角色的数据库中
                    _.set(variables, `stat_data.char.${charId}[0].name`, [generatedData.name, "String. 角色的名字。"]);
                    _.set(variables, `stat_data.char.${charId}[0].traits`, [generatedData.traits, "String. 角色的性格特性。"]);
                    // 将状态从“待初始化”更新为“已锁定”，表示生成完成
                    _.set(variables, `stat_data.char.${charId}[0].status`, ["locked", "String. 审查状态。"]);

                    updateNeeded = true; // 标记需要执行一次变量更新

                    // --- 步骤5: 宣告角色登场 ---
                    const narrativeText = `[警报：检测到新的求生信号... 身份验证已通过... 生物特征正在注册...]\n\n一位名叫【${generatedData.name}】的新来客出现在了隔离室的监视器上，等待您的审查。`;
                    await createChatMessages([{ role: 'system', message: narrativeText }]);

                    console.log(`Kora-Generator: Successfully generated character ${generatedData.name} (${charId}).`);
                }
            }

            // 如果执行了生成，则返回更新后的变量对象
            if (updateNeeded) {
                return variables;
            }

        } catch (e) {
            console.error("Kora-Generator Error:", e);
        }
    }

    // Kora注：确保MVU框架已加载，然后将我们的生成函数挂载到“变量更新结束”事件上。
    if (window.Mvu && Mvu.events) {
        eventOn(Mvu.events.VARIABLE_UPDATE_ENDED, supervisedGeneration);
        console.log('Kora-Generator: Script loaded and listening for initializing characters.');
    } else {
        console.error('Kora-Generator: MVU framework not detected. This script will not function.');
    }
})();

