    /**
     * [UI更新与替换函数]
     * Kora觉得：此函数负责在SillyTavern渲染一条新消息时被触发，执行UI的替换逻辑。
     * @param {number} message_id - 触发事件的消息ID。
     */
    async function updateStatusBlock(message_id) {
        try {
            // 获取原始消息内容
            const messageElement = retrieveDisplayedMessage(message_id);
            if (!messageElement || messageElement.length === 0) return;

            const rawMessageHTML = messageElement.find('.mes_text').html();

            // 检查消息中是否包含我们的占位符，如果没有则直接退出
            if (!rawMessageHTML || !STATUS_PLACEHOLDER.test(rawMessageHTML)) return;

            // [核心步骤] 调用酒馆助手API，获取该消息对应的、最权威的stat_data
            const variables = await getVariables({ type: 'message', message_id: message_id });

            // 如果没有stat_data，说明变量尚未初始化，不进行渲染
            if (!variables || !variables.stat_data) {
                console.warn(`[Kora UI Engine] 消息 #${message_id} 缺少stat_data，跳过渲染。`);
                return;
            }

            // 调用我们的核心渲染函数，传入数据，生成UI面板
            const statusContainer = generateStatusBlock(variables);

            // 使用JQuery的 .html() 方法进行替换，可以更精确地处理HTML字符串
            const updatedHTML = rawMessageHTML.replace(STATUS_PLACEHOLDER, statusContainer.innerHTML);
            messageElement.find('.mes_text').html(updatedHTML);

        } catch (error) {
            console.error('[Kora UI Engine] 渲染状态栏时发生错误:', error);
        }
    }


    /**
     * [脚本初始化函数]
     * Kora觉得：这是让脚本“活”起来的关键。我们使用`eventOn` API来监听SillyTavern的内部事件。
     */
    async function initializeStatusBlocks() {
        console.log('[Kora UI Engine] 初始化状态栏渲染引擎。');
        // 监听“角色消息渲染完成”事件，每次AI的新回复显示时，都尝试执行我们的UI更新函数
        eventOn('character-message-rendered', updateStatusBlock);

        // Kora觉得：为了处理编辑、重绘等情况，监听MESSAGE_UPDATED同样重要。
        eventOn('message-updated', updateStatusBlock);

        // 为了确保页面加载时已有的历史消息也能被渲染，我们遍历一次所有消息。
        const chatMessages = await getChatMessages({ start: 0, end: -1, role: 'assistant' });
        for (const msg of chatMessages) {
            await updateStatusBlock(msg.id);
        }
    }

    // 启动脚本
    initializeStatusBlocks();

})();

