// name: 外出管理器 (OutingManager) v1.1 (回归调度版)
(async () => {
    // 内部追踪器，用于存储所有外出角色的回归信息
    const trackedCharacters = {}; // 格式: { charId: { returnTimestamp: 'YYYY-MM-DD HH:MM', ... } }

    /**
     * 将'YYYY-MM-DD HH:MM'格式的时间字符串转换为Date对象
     * @param {string} timestampStr - 时间戳字符串
     * @returns {Date}
     */
    function parseTimestamp(timestampStr) {
        return new Date(timestampStr.replace(' ', 'T'));
    }

    /**
     * 事件处理器：当一个角色被批准外出时调用
     * @param {CustomEvent} event - 包含 detail: { charId, returnTimestamp, ... }
     */
    function handleCharacterDeparted(event) {
        const { charId, returnTimestamp } = event.detail;
        if (!charId || !returnTimestamp) return;

        trackedCharacters[charId] = { returnTimestamp, detail: event.detail }; // 保存全部细节以供回归时使用
        console.log(`Kora-OutingManager: Tracking ${charId}. Scheduled to return at ${returnTimestamp}.`);
    }

    /**
     * 事件处理器：当游戏时间更新时调用，检查是否有人需要回归
     */
    async function checkReturnTimers() {
        try {
            const variables = getVariables({ type: 'chat' });
            const currentDate = _.get(variables, 'stat_data.world.date[0]');
            const currentTime = _.get(variables, 'stat_data.world.time[0]');
            if (!currentDate || !currentTime) return;

            const now = parseTimestamp(`${currentDate} ${currentTime}`);
            const charactersToReturn = [];

            for (const charId in trackedCharacters) {
                let returnTime = parseTimestamp(trackedCharacters[charId].returnTimestamp);

                // Kora注：新增的回归时间智能调度约束
                // 如果原定回归时间在凌晨0点到8点之间
                if (returnTime.getHours() >= 0 && returnTime.getHours() < 8) {
                    // 将回归时间统一调整到当天早上8点后一个随机的小时间（例如8:05）
                    returnTime.setHours(8, 5, 0, 0);
                    console.log(`Kora-OutingManager: Adjusted return time for ${charId} to post-broadcast time.`);
                }

                // 使用调整后的时间进行判断
                if (now >= returnTime) {
                    charactersToReturn.push(charId);
                }
            }

            if (charactersToReturn.length > 0) {
                for (const charId of charactersToReturn) {
                    console.log(`Kora-OutingManager: ${charId} is due to return. Dispatching event.`);
                    // 派发“角色回归待定”事件，通知经验管理器开始处理复杂的回归序列
                    document.dispatchEvent(new CustomEvent('KoraEvents.CHARACTER_RETURN_PENDING', { detail: trackedCharacters[charId].detail }));
                    // 从追踪器中移除
                    delete trackedCharacters[charId];
                }
            }
        } catch (e) {
            console.error("Kora-OutingManager (checkReturnTimers) Error:", e);
        }
    }

    // 监听“角色离开”事件，以添加追踪
    document.addEventListener('KoraEvents.CHARACTER_DEPARTED', handleCharacterDeparted);
    // 监听“时间更新”事件，以检查回归
    document.addEventListener('KoraEvents.TIME_UPDATED', checkReturnTimers);

    console.log('Kora-OutingManager v1.1 (Return Scheduler): Script loaded.');
})();

