// name: 空间个性化管理器 v2.0 (动机版)
(async () => {
    /**
     * 核心处理器：当一个新住户入住时触发
     */
    async function handleFirstTimeDecoration(event) {
        try {
            const { charId, roomId } = event.detail;
            if (!charId || !roomId) return;
            const variables = getVariables({ type: 'chat' });
            const charData = _.get(variables, `stat_data.char.${charId}.[0]`);
            if (!charData) return;
            const personalBelongings = charData.personal_belongings[0] || [];
            if (personalBelongings.length === 0) return;
            await updateVariablesWith(vars => {
                const decorationPath = `stat_data.rooms.${roomId}.decorations[0]`;
                const currentDecorations = _.get(vars, decorationPath, []);
                _.set(vars, decorationPath, _.union(currentDecorations, personalBelongings));
                return vars;
            }, { type: 'chat' });
            const narrative = `[SYSTEM]: ${charData.name[0]} 在安顿下来后，开始从她的行李中拿出一些个人物品来装饰这个略显冰冷的房间：${personalBelongings.join('、')}。`;
            await createChatMessages([{ role: 'system', message: narrative, is_hidden: true }]);
        } catch (e) {
            console.error("Kora-DecorationManager (Initial) Error:", e);
        }
    }

    /**
     * 新增：持续装饰处理器
     * 监听AI回复，处理 <Kora_Place_Item /> 指令
     */
    async function handleOngoingDecoration(message_id) {
        const messageData = (await getChatMessages(message_id))[0];
        if (!messageData || messageData.role !== 'assistant' || messageData.is_hidden) return;

        const content = messageData.message;
        const placeRegex = /<Kora_Place_Item\s+item="([^"]+)"\s*\/?>/g;
        let match;
        let contentModified = false;
        let finalContent = content;

        while ((match = placeRegex.exec(content)) !== null) {
            contentModified = true;
            finalContent = finalContent.replace(match[0], '');
            const itemToPlace = match[1];

            // 确定是谁放置的物品
            var last_message = getvar('main.raw_prompt').split('### Instruction:')[0].trim().split('\n').pop();
            var speaker_match = last_message.match(/^([^：:]+)[：:]/);
            if (!speaker_match) continue;

            const speaker_name = speaker_match[1].trim();
            const variables = getVariables({ type: 'chat' });
            const allChars = _.get(variables, 'stat_data.char', {});
            const speakerId = Object.keys(allChars).find(id => _.get(allChars[id], '[0].name[0]') === speaker_name);

            if (speakerId) {
                const charData = allChars[speakerId][0];
                const roomId = charData.current_room[0];
                const belongings = charData.personal_belongings[0] || [];

                // 检查行李中是否有该物品
                if (belongings.includes(itemToPlace) && roomId && roomId !== "公寓外") {
                    await updateVariablesWith(vars => {
                        // 从行李中移除
                        const belongingsPath = `stat_data.char.${speakerId}.[0].personal_belongings[0]`;
                        const currentBelongings = _.get(vars, belongingsPath, []);
                        _.set(vars, belongingsPath, currentBelongings.filter(item => item !== itemToPlace));

                        // 添加到房间装饰中
                        const decorationPath = `stat_data.rooms.${roomId}.decorations[0]`;
                        const currentDecorations = _.get(vars, decorationPath, []);
                        if (!currentDecorations.includes(itemToPlace)) {
                            currentDecorations.push(itemToPlace);
                            _.set(vars, decorationPath, currentDecorations);
                        }
                        return vars;
                    }, { type: 'chat' });
                }
            }
        }

        if (contentModified) {
            await setChatMessages([{ message_id, message: finalContent.trim() }], { refresh: 'affected' });
        }
    }

    // 脚本初始化
    if (window.Mvu && Mvu.events) {
        document.addEventListener('KoraEvents.RESIDENT_MOVED_IN', handleFirstTimeDecoration);
        eventOn(tavern_events.MESSAGE_RECEIVED, handleOngoingDecoration);
        console.log('Kora-DecorationManager v2.0 (Motivation Edition): Script loaded.');
    }
})();

