            const pathAtoB = `${matrixPath}.${charIdA}.${charIdB}`;
            const currentRelA = _.get(vars, pathAtoB, 50);
            _.set(vars, pathAtoB, Math.max(0, Math.min(currentRelA + change, 100)));
            const pathBtoA = `${matrixPath}.${charIdB}.${charIdA}`;
            const currentRelB = _.get(vars, pathBtoA, 50);
            _.set(vars, pathBtoA, Math.max(0, Math.min(currentRelB + change, 100)));
            return vars;
        });
    }

    async function handleSocialAction(oldVars, newVars) {
        // ... (基于行动的判定逻辑保持不变)
    }

    /**
     * 新增：对话情感分析处理器
     * @param {CustomEvent} event - 包含 detail: { participants: string[], log: string[] }
     */
    async function analyzeConversation(event) {
        try {
            const conversation = event.detail;
            if (!conversation || conversation.participants.length < 2 || conversation.log.length === 0) return;

            const dialogue_snippet = conversation.log.join('\n');
            const promptEntry = (await SillyTavern.loadWorldInfo('[PROMPT_ANALYZE_SENTIMENT]'))?.entries?.[0];
            if (!promptEntry) return;

            const prompt = promptEntry.content.replace('{{dialogue_snippet}}', dialogue_snippet);
            const sentiment = await generate({ user_input: prompt });

            let change = 0;
            if (sentiment.includes('positive')) change = 3;
            else if (sentiment.includes('negative')) change = -5;

            if (change !== 0) {
                const allChars = getVariables({ type: 'chat' }).stat_data.char;
                const nameToId = _.mapValues(_.invert(_.mapValues(allChars, c => c[0].name[0])));
                const charA_id = nameToId[conversation.participants[0]];
                const charB_id = nameToId[conversation.participants[1]];
                if (charA_id && charB_id) {
                    await applyRelationshipChange(charA_id, charB_id, change);
                    console.log(`Kora-SocialManager: Relationship between ${conversation.participants.join(' and ')} changed by ${change} due to dialogue sentiment.`);
                }
            }
        } catch(e) { console.error("Kora-SocialManager(Dialogue) Error:", e); }
    }

    if (window.Mvu && Mvu.events) {
        eventOn(Mvu.events.VARIABLE_UPDATE_ENDED, handleSocialAction);
        // 新增监听器：监听“对话结束”事件
        document.addEventListener('KoraEvents.CONVERSATION_ENDED', analyzeConversation);
        console.log('Kora-SocialManager v3.0 (Context-Aware): Script loaded.');
    }
})();

