// name: 欲望管理器 v1.0
(async () => {
    /**
     * 核心处理器：监听并处理arousal值的更新指令
     * @param {number} message_id - 消息ID
     */
    async function handleArousalUpdate(message_id) {
        try {
            const messageData = (await getChatMessages(message_id))[0];
            // Kora注：此指令可由AI或玩家发起
            if (!messageData || messageData.is_hidden) return;

            const content = messageData.message;
            const arousalRegex = /<Kora_Update_Arousal\s+change="([+-]?\d+)"[^>]*\/?>/g;
            let match;
            let contentModified = false;
            let finalContent = content;

            // 寻找发出指令的角色
            var last_message = getvar('main.raw_prompt').split('### Instruction:')[0].trim().split('\n').pop();
            var speaker_match = last_message.match(/^([^：:]+)[：:]/);
            var speaker_name = speaker_match ? speaker_match[1].trim() : null;
            if (messageData.role === 'user') speaker_name = getvar('user_name');

            if (!speaker_name) return;

            while ((match = arousalRegex.exec(content)) !== null) {
                contentModified = true;
                finalContent = finalContent.replace(match[0], '');
                const changeValue = parseInt(match[1], 10);

                if (isNaN(changeValue)) continue;

                const variables = getVariables({ type: 'chat' });
                const allChars = _.get(variables, 'stat_data.char', {});
                const speakerId = Object.keys(allChars).find(id => _.get(allChars[id], '[0].name[0]') === speaker_name);

                if (speakerId) {
                    await updateVariablesWith(vars => {
                        const arousalPath = `stat_data.char.${speakerId}.[0].arousal[0]`;
                        const currentArousal = _.get(vars, arousalPath, 0);
                        let newArousal = currentArousal + changeValue;

                        // Kora注：将数值严格约束在0-100之间
                        newArousal = Math.max(0, Math.min(newArousal, 100));

                        _.set(vars, arousalPath, newArousal);
                        return vars;
                    }, { type: 'chat' });
                }
            }

            if (contentModified) {
                await setChatMessages([{ message_id, message: finalContent.trim() }], { refresh: 'affected' });
            }

        } catch (e) {
            console.error("Kora-DesireManager Error:", e);
        }
    }

    // 脚本初始化
    if (window.Mvu && Mvu.events) {
        eventOn(tavern_events.MESSAGE_RECEIVED, handleArousalUpdate);
        eventOn(tavern_events.MESSAGE_SENT, handleArousalUpdate);
        console.log('Kora-DesireManager v1.0: Script loaded and active.');
    }
})();

// [Tavern Helper Script]
// name: 遭遇管理器 v1.0
(async () => {
    let lastEncounter = { user: '', char: '', room: '' };

    async function checkEncounters(oldVars, newVars) {
        try {
            const userRoom = _.get(newVars, 'stat_data.user.current_room[0]');
            if (!userRoom || _.get(oldVars, 'stat_data.user.current_room[0]') === userRoom) return; // User没移动，不触发

            const allChars = _.get(newVars, 'stat_data.char', {});
            const charsInRoom = Object.keys(allChars).filter(id => _.get(allChars[id], '[0].current_room[0]') === userRoom);

            if (charsInRoom.length > 0) {
                const charToEncounterId = charsInRoom[0]; // 简化：只遭遇第一个角色

                // 防止重复触发
                if (lastEncounter.user === getvar('user_name') && lastEncounter.char === charToEncounterId && lastEncounter.room === userRoom) return;
                lastEncounter = { user: getvar('user_name'), char: charToEncounterId, room: userRoom };

                const charData = allChars[charToEncounterId][0];
                const promptEntry = (await SillyTavern.loadWorldInfo('[PROMPT_GENERATE_ENCOUNTER]'))?.entries?.[0];
                if (!promptEntry) return;

                let encounterPrompt = promptEntry.content
                    .replace('{{room_name}}', userRoom)
                    .replace('{{character_name}}', charData.name[0])
                    .replace('{{character_faction}}', charData.faction[0])
                    .replace('{{character_traits}}', charData.traits[0])
                    .replace('{{character_goal}}', charData.current_goal[0]);

                const scene = await generate({ user_input: encounterPrompt });
                await createChatMessages([{ role: 'assistant', message: scene }]);
            }
        } catch (e) { console.error("Kora-EncounterManager Error:", e); }
    }

    if (window.Mvu && Mvu.events) {
        eventOn(Mvu.events.VARIABLE_UPDATE_ENDED, checkEncounters);
        console.log('Kora-EncounterManager v1.0: Script loaded.');
    }
})();

(async () => {
    let activeConversation = null;

    function endCurrentConversation() {
        if (activeConversation && activeConversation.log.length > 1) {
            console.log('Kora-ConversationManager: Conversation ended. Dispatching event.');
            document.dispatchEvent(new CustomEvent('KoraEvents.CONVERSATION_ENDED', { detail: activeConversation }));
        }
        activeConversation = null;
    }

    async function handleMessage(message_id) {
        const msg = (await getChatMessages(message_id))?.[0];
        if (!msg || msg.is_system || msg.is_hidden) return;

        const speakerName = msg.name;
        const isUser = msg.is_user;

        // 如果是玩家发言，或者发言者不是当前对话的参与者，则结束上一场对话
        if (isUser || (activeConversation && !activeConversation.participants.includes(speakerName))) {
            endCurrentConversation();
        }

        // 如果是NPC发言，则开始或继续一场对话
        if (!isUser) {
            if (!activeConversation) {
                activeConversation = { participants: [speakerName], log: [], startTime: Date.now() };
            }

            // 如果有新的NPC加入对话
            if (!activeConversation.participants.includes(speakerName)) {
                activeConversation.participants.push(speakerName);
            }

            activeConversation.log.push(`${speakerName}: ${msg.message}`);
            activeConversation.lastTimestamp = Date.now();
        }
    }

    // 定时检查超时的对话
    setInterval(() => {
        if (activeConversation && (Date.now() - activeConversation.lastTimestamp > 30000)) { // 30秒无新消息则超时
            console.log('Kora-ConversationManager: Conversation timed out.');
            endCurrentConversation();
        }
    }, 5000);

    if (window.Mvu && Mvu.events) {
        eventOn(tavern_events.MESSAGE_RECEIVED, handleMessage);
        eventOn(tavern_events.MESSAGE_SENT, handleMessage);
        console.log('Kora-ConversationManager v1.0: Script loaded.');
    }
})();

// [Tavern Helper Script]
// name: 小剧场管理器 v2.0 (后台脚本版)
(async () => {
    /**
     * 核心处理器：在AI回复后，检查并生成小剧场
     * @param {number} message_id - AI回复的消息ID
     */
    async function generateMiniTheater(message_id) {
        try {
            const msg = (await getChatMessages(message_id))?.[0];
            // 只在常规的AI回复后触发，避免在系统消息或指令处理中运行
            if (!msg || msg.is_user || msg.is_system || msg.is_hidden) return;

            const variables = getVariables({ type: 'chat' });
            const userRoom = _.get(variables, 'stat_data.user.current_room[0]');
            const allChars = _.get(variables, 'stat_data.char', {});
            const scenePrompts = [];

            if (allChars && userRoom) {
                for (const id in allChars) {
                    const char = _.get(allChars, `${id}.[0]`);
                    if (char.status === 'in_apartment' && char.current_room !== userRoom && char.current_goal && char.current_goal !== '[NEEDS_NEW_GOAL]') {
                        if (Math.random() < 0.25) { // 25%概率触发
                            scenePrompts.push({
                                location: char.current_room,
                                prompt: `You are a silent, observational narrator. Describe what ${char.name[0]} is doing right now in the ${char.current_room}. Their current goal is: "${char.current_goal[0]}". Be brief, atmospheric, and respond with only the description paragraph.`
                            });
                        }
                    }
                }
            }

            if (scenePrompts.length > 0) {
                let theaterBlock = '\n\n---\n<MiniTheater>\n';

                for (const scene of scenePrompts) {
                    const sceneText = await generate({ user_input: scene.prompt });
                    if (sceneText) {
                        theaterBlock += `  <Scene location="${scene.location}">\n    ${sceneText.trim()}\n  </Scene>\n`;
                    }
                }
                theaterBlock += '</MiniTheater>';

                // 将生成的小剧场追加到AI的原始回复末尾
                const originalMessage = msg.message;
                await setChatMessages([{ message_id, message: originalMessage + theaterBlock }]);
            }

        } catch (e) {
            console.error("Kora-MiniTheaterManager Error:", e);
        }
    }

    // 脚本初始化
    if (window.Mvu && Mvu.events) {
        // 监听AI消息生成完毕的事件
        eventOn(tavern_events.MESSAGE_RECEIVED, generateMiniTheater);
        console.log('Kora-MiniTheaterManager v2.0 (Backend Edition): Script loaded.');
    }
})();

